import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // root object
  const root = new Group();

  // geometry & material
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ transparent: true });
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // texture loading (async, but function stays sync)
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // apply cinematic primitives if any
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        const handle = fn(root, prim.params);
        if (handle) primitiveHandles.push(handle);
      }
    }
  }

  // no text content handling needed (none)

  // event handlers placeholder
  root.userData.handlers = {};

  // cleanup routine
  root.userData.cleanup = () => {
    // dispose texture
    if (loadedTexture) {
      loadedTexture.dispose();
      loadedTexture = null;
    }
    // dispose material & geometry
    material.dispose();
    geometry.dispose();
    // cleanup primitives
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
    // kill any GSAP timelines/tweens attached to this node
    gsap.killTweensOf(root);
  };

  return root;
}
